export type FunctionalIconName = keyof typeof functionalIconArtwork | keyof typeof originalIconArtwork | "Back" | "Warn" | "Stop" | "Code2" | "CodeXml" | "History" | "RotateCcwClock" | "FolderFill" | "FolderOpenFill" | "Loader" | "KeyRound" | "Link2" | "FilePlus2" | "NotebookPen" | "Box" | "BrainCircuit" | "SlidersHorizontal" | "SquareStack";

const canonicalAliases: Partial<Record<FunctionalIconName, FunctionalIconName>> = {
  "Back": "ChevronLeft",
  "Warn": "TriangleAlert",
  "Stop": "Square",
  "Code2": "Code",
  "CodeXml": "Code",
  "History": "Clock",
  "RotateCcwClock": "Clock",
  "FolderFill": "Folder",
  "FolderOpenFill": "FolderOpen",
  "Loader": "LoaderCircle",
  "KeyRound": "Key",
  "Link2": "Link",
  "FilePlus2": "FilePlus",
  "NotebookPen": "FilePenLine",
  "Box": "Package",
  "BrainCircuit": "Brain",
  "SlidersHorizontal": "Settings2",
  "SquareStack": "Layers"
};

export function functionalIconSvg(name: FunctionalIconName, size = 16): string {
  const pixelSize = Number.isFinite(size) && size > 0 ? size : 16;
  const canonical = canonicalAliases[name] ?? name;
  const svg = functionalIconArtwork[canonical as keyof typeof functionalIconArtwork];
  // Legacy identifiers without retained custom artwork use their original glyph.
  if (!svg) return originalIconSvg(name, pixelSize);
  return svg.replace('width="24" height="24"', `width="${pixelSize}" height="${pixelSize}" aria-hidden="true" focusable="false" data-functional-icon="${canonical}"`);
}
